            for (int j = 0; j < 5; j++)
                for (int k = 0; k < 5; k++)
                    for (int l = 0; l <= t; l++)
                        for (int m = 0; m <= t; m++)
                            dp[i][j][k][l][m] = -1;
        System.out.println(count(n, t, dp));
