    static int count(int n, int t, int[][][][][] dp) {
        int res = 0;
        for (int y1 = 1; y1 <= 4; y1++)
            for (int y2 = 1; y2 <= 4; y2++) {
                if (y1 == y2) continue;
                res += rec(n, 2, y1, y2, 0, 0, t, dp);
            }
        return res;
    }

    static int rec(int n, int pos, int prev, int curr, int humps, int valleys, int t, int[][][][][] dp) {
        if (pos == n) return (humps == t && valleys == t - 1) ? 1 : 0;
        if (dp[pos][prev][curr][humps][valleys] != -1)
            return dp[pos][prev][curr][humps][valleys];
        int res = 0;
        for (int next = 1; next <= 4; next++) {
            if (next == curr) continue;
            int newHumps = humps, newValleys = valleys;
            if (pos >= 2) {
                if (prev < curr && curr > next) newHumps++;
                if (prev > curr && curr < next) newValleys++;
            }
            if (newHumps > t || newValleys > t - 1) continue;
            res += rec(n, pos + 1, curr, next, newHumps, newValleys, t, dp);
        }
        return dp[pos][prev][curr][humps][valleys] = res;
    }
